const notice=value=>{$('notice').textContent=value;$('notice').hidden=!value;};
const dates=v=>String(v??'').replace('T',' ').replace(/\.\d+Z$/,' UTC');
const money=v=>v===null||v===undefined?'Unknown':String(v)+' USD';
function table(head,rows){return '<div class="table"><table><thead><tr>'+head.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'x-research-token':token,...(body===undefined?{}:{'content-type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)})});const value=await r.json();if(!r.ok)throw new Error(value.message??value.error);return value;}
async function file(path){const r=await fetch(path,{headers:{'x-research-token':token}});if(!r.ok){const e=await r.json();throw new Error(e.message??e.error);}return r;}
async function download(path,name){const response=await file(path),url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=/filename="([^"]+)"/.exec(response.headers.get('content-disposition')??'')?.[1]??name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function guarded(fn){return async event=>{event?.preventDefault();if(state.busy)return;state.busy=true;document.querySelectorAll('form button').forEach(b=>b.disabled=true);try{notice('');await fn(event);}catch(e){notice(e.message);}finally{state.busy=false;document.querySelectorAll('form button').forEach(b=>b.disabled=false);applySourceMode();}};}
function selected(){const r=state.workspace?.fundingReports.reports.find(r=>r.id===state.selected);if(!r)throw new Error('Select a saved report.');return r;}
function applySourceMode(){const capture=$('source-mode').value==='capture';$('capture-fields').hidden=!capture;$('report-fields').hidden=capture;$('capture').required=capture;$('capture').disabled=!capture;$('source-report').required=!capture;$('source-report').disabled=capture;$('buyer-form').querySelector('button').disabled=state.busy||!state.workspace?.server.receivingEnabled;}
