    attempt.intentId===context.identity.intentId&&attempt.createdAt===context.identity.attemptCreatedAt&&
    attempt.configSha256===context.identity.configurationSha256&&
    attempt.bodySha256===context.identity.bodySha256,
    'ACCOUNTING_ARCHIVED_ATTEMPT_CHANGED');
}

async function workspacePins(context){
  for(const key of ['configuration','manifest']){
    const descriptor=context.workspaceSource?.[key];
    need(descriptor?.path===join(context.request.workspaceDirectory,
      key==='configuration'?'operator.json':'workspace.json'),'ACCOUNTING_WORKSPACE_SOURCE_INVALID');
    const source=await accountingPrivateFile(descriptor.path);
    need(sameAccountingValue(source.descriptor,descriptor),'ACCOUNTING_ORIGINAL_WORKSPACE_CHANGED');
  }
}

export async function finalizeSelectedNodeAttempt(contextPath,contextSha256,{signal}={}){
  need(HASH.test(contextSha256??''),'ACCOUNTING_CONTEXT_DIGEST_REQUIRED');
  const input=await accountingPrivateFile(absolute(contextPath),262144),context=parseJson(input.raw);
  need(input.descriptor.sha256===contextSha256&&digest(jsonBytes(context))===contextSha256&&
    context.schema===OPERATION_ACCOUNTING_COMMAND&&
    contextPath===join(context.commandDirectory,'context.json')&&
    /^finalize-[A-Za-z0-9]{6}$/.test(context.commandId??'')&&
    context.commandDirectory===join(context.identity.operationDirectory,'accounting',context.commandId)&&
    context.identity.operationDirectory===join(context.identity.stateDirectory,digest(context.identity.intentId))&&
    time(context.startedAt)&&Number.isSafeInteger(context.resultLimit)&&
    context.resultLimit>=65536&&context.resultLimit<=4_194_304,
    'ACCOUNTING_CONTEXT_CHANGED');
  need(context.execution.worker.path===here&&
    context.execution.adapter.path===fileURLToPath(new URL('./operation-accounting.mjs',import.meta.url))&&
    await realpath(context.execution.node)===await realpath(process.execPath),
    'ACCOUNTING_SELECTED_WORKER_CHANGED');
  await verifyCode(context.execution.worker);await verifyCode(context.execution.adapter);
  const root=absolute(context.execution.runtimeDirectory);
  need(root===context.execution.runtimeDirectory&&await realpath(root)===root,
    'ACCOUNTING_RUNTIME_CANONICAL_PATH_REQUIRED');
  const required=['config.mjs','workspace.mjs','finalization.mjs',
    '../sf36-spend-governor/finalize.py','../sf86-rpc-transfer-reconcile/cli.mjs',
    '../sf86-rpc-transfer-reconcile/terms.mjs'].map(path=>resolve(root,path));
  need(Array.isArray(context.execution.originalSource)&&
    context.execution.originalSource.length===required.length&&
    context.execution.originalSource.every((value,index)=>value.path===required[index]),
    'ACCOUNTING_ORIGINAL_IMPLEMENTATION_REQUIRED');
  for(const descriptor of context.execution.originalSource)await verifyCode(descriptor);

  // The loaded SDK reads its own original Operation contract. Its selected
  // runtime supplies the maintained financial implementation; the producing
  // runtime and exact attempt remain in context.identity.
  const {Buyer}=await import('./client.mjs');
  const buyer=new Buyer({runtimeDirectory:root,stateDirectory:context.identity.stateDirectory,
    node:context.execution.node,environment:process.env,outputLimit:context.resultLimit});
  const operation=buyer.operation(context.identity.intentId);
  const source=await readOperationAccountingSource(operation,{requireEnded:true,signal});
  await verifySavedSource(context,source);
  const [{config,execution},{openWorkspace},financial,{readAttemptWireCheckpoint}]=await Promise.all([
    importOriginal(root,'config.mjs'),importOriginal(root,'workspace.mjs'),
    importOriginal(root,'finalization.mjs'),importOriginal(root,'attempt-wire.mjs'),
  ]);
  need(typeof financial.runOriginalFinalityWorker==='function'&&
    typeof financial.readUnpaidAttempt==='function','ACCOUNTING_ORIGINAL_FINALITY_API_REQUIRED');
  const cfg=await config(operation.configPath),{op,owner,transport}=execution(cfg);
  need(sameAccountingValue(cfg,source.config)&&op.intentId===source.identity.intentId,
    'ACCOUNTING_ORIGINAL_CONFIGURATION_CHANGED');
  const wire=await readAttemptWireCheckpoint({cfg,body:source.identity.bodyPresent?source.body:undefined});
  need(wire===null||wire?.writerActive===false,'ACCOUNTING_PRODUCING_WRITER_LIVE');
  const base={schema:OPERATION_ACCOUNTING_NATIVE,contextSha256,identity:context.identity,
    workspace:context.request.workspaceDirectory,workspaceSource:context.workspaceSource,
    accountingRuntimeDirectory:root,evidencePath:source.evidencePath,
    evidenceSha256:source.files.evidence.sha256,attemptSnapshotSha256:context.source.attempt.sha256,
    observedAttemptSha256:source.files.attempt.sha256,producer:source.producer};
  const unpaid=await financial.readUnpaidAttempt({evidencePath:source.evidencePath,
    intentId:op.intentId,attemptStartedAt:source.identity.attemptCreatedAt});
  if(unpaid!==null){
    await verifySavedSource(context,await readOperationAccountingSource(operation,{requireEnded:true,signal}));
    return{...base,kind:'UNPAID_RESPONSE',approvedRequestSha256:null,result:unpaid,
      completedAt:new Date().toISOString(),recordAuthority:'ORIGINAL_UNSIGNED_RESPONSE'};
  }

  need(typeof context.request.workspaceDirectory==='string',
    'ACCOUNTING_ORIGINAL_WORKSPACE_REQUIRED');
  await accountingPrivateDirectory(context.request.workspaceDirectory);
  await workspacePins(context);
  const active=await openWorkspace(['--dir',context.request.workspaceDirectory]);
  const current=execution(active.config);
  need(['python','actor','service','policy','ledger'].every(key=>owner[key]===current.owner[key])&&
    cfg.trustedPayer===active.config.trustedPayer&&
    sameAccountingValue(transport,current.transport)&&
    ['scheme','network','asset','payTo'].every(key=>op.expect[key]===current.op.expect[key])&&
    (source.identity.nativeWorkspace===null||
      source.identity.nativeWorkspace===active.manifest.directory&&cfg.signerModule===active.config.signerModule),
    'ACCOUNTING_ORIGINAL_OPERATOR_WORKSPACE_MISMATCH');
  // A separately reviewed fromConfig/SF103 signer retains the same authenticated
  // owner, ledger, payer and operation. Historical signer/cap changes do not
  // invalidate a reservation already authenticated by original SF36.
  const [{originalRecordFromEvidence},{checkOriginalTerms,resolveRpcEndpoint},{resolveBuyerProxy}]=await Promise.all([
    importOriginal(root,'../sf86-rpc-transfer-reconcile/cli.mjs'),
    importOriginal(root,'../sf86-rpc-transfer-reconcile/terms.mjs'),
    importOriginal(root,'../sf31-buyer-client/public-transport.mjs'),
  ]);
  const evidence=parseJson(source.evidenceRaw),record=originalRecordFromEvidence(evidence);
  checkOriginalTerms(record,active.config.trustedPayer);
  const approved=record.operatorReservation?.approved_request;
  const approvedSha256=record.operatorReservation?.request_sha256;
  need(object(approved)&&Object.keys(approved).sort().join('\n')===requestFields.join('\n')&&
    HASH.test(approvedSha256??'')&&HASH.test(approved.accepted_terms_sha256??'')&&
    approved.request_id===op.intentId&&approved.actor===owner.actor&&approved.service===owner.service&&
    approved.resource===new URL(op.url).href&&approved.method===op.method&&
    approved.body_present===source.identity.bodyPresent&&approved.body_bytes===source.identity.bodyBytes&&
    approved.body_sha256===source.identity.bodySha256&&
    ['scheme','network','asset'].every(key=>approved[key]===op.expect[key])&&
    approved.pay_to===op.expect.payTo&&/^[1-9][0-9]*$/.test(approved.max_amount??'')&&
    BigInt(approved.max_amount)<=BigInt(op.expect.maxAtomic)&&
    Number.isSafeInteger(approved.max_timeout_seconds)&&approved.max_timeout_seconds>=1&&
    approved.max_timeout_seconds<=86400&&
    (op.expect.maxTimeoutSeconds===undefined||approved.max_timeout_seconds<=op.expect.maxTimeoutSeconds)&&
    evidence.intentId===op.intentId&&time(evidence.observedAt)&&
    Date.parse(evidence.observedAt)>=Date.parse(source.identity.attemptCreatedAt),
    'ACCOUNTING_ORIGINAL_APPROVED_REQUEST_CHANGED');
  need(source.evidencePath===join(cfg.evidenceDir,digest(op.intentId)+'.json')&&
    (source.identity.nativeWorkspace===null||cfg.evidenceDir===active.config.evidenceDir),
    'ACCOUNTING_ORIGINAL_EVIDENCE_DIRECTORY_CHANGED');
  const rpcEndpoint=resolveRpcEndpoint(op.expect.network,active.manifest.signer.rpcUrl);
  let rpcProxyUrl;
  if(current.transport!==null){
    resolveBuyerProxy(current.transport);
    rpcProxyUrl=new URL(current.transport.proxyEnv===undefined?
      current.transport.proxyUrl:process.env[current.transport.proxyEnv]).origin;
  }
  need((context.request.outboxDirectory===null)===(context.request.merchantRoute===null),
    'OUTBOX_AND_ORIGINAL_MERCHANT_ROUTE_REQUIRED_TOGETHER');
  if(context.request.outboxDirectory!==null){
    await accountingPrivateDirectory(context.request.outboxDirectory);
    need(typeof context.request.merchantRoute==='string'&&/^[A-Za-z0-9_-]{1,80}$/.test(context.request.merchantRoute),
      'ACCOUNTING_MERCHANT_ROUTE_INVALID');
  }
  await workspacePins(context);
  await verifySavedSource(context,await readOperationAccountingSource(operation,{requireEnded:true,signal}));
  const privileged=await openWorkspace(['--dir',context.request.workspaceDirectory],{accounting:true});
  need(sameAccountingValue(privileged.config,active.config)&&
    sameAccountingValue(privileged.manifest,active.manifest),'ACCOUNTING_ORIGINAL_WORKSPACE_CHANGED');
  const reports=await accountingPrivateDirectory(join(context.commandDirectory,'reports'),{create:true});
  const args=['--record',source.evidencePath,'--ledger',owner.ledger,'--policy',owner.policy,
    '--payer',active.config.trustedPayer,'--node',context.execution.node,'--reports',reports,
    '--rpc-endpoint',rpcEndpoint,'--expected-request-sha',approvedSha256,
    ...(rpcProxyUrl===undefined?[]:['--rpc-proxy-env','SF36_RPC_PROXY_URL']),
    ...(context.request.outboxDirectory===null?[]:[
      '--outbox',context.request.outboxDirectory,'--merchant-route',context.request.merchantRoute])];
  const result=await financial.runOriginalFinalityWorker(owner.python,args,
    privileged.operatorEnvironment,signal,rpcProxyUrl);
  if(FINALIZED.has(result.outcome))need(result.request_id===op.intentId&&
    result.request_sha256===approvedSha256,'ACCOUNTING_FINALIZED_REQUEST_CHANGED');
  return{...base,kind:'PAID_FINALIZATION',approvedRequestSha256:approvedSha256,result,
    operator:{python:owner.python,actor:owner.actor,service:owner.service,
      policy:owner.policy,ledger:owner.ledger,payer:active.config.trustedPayer},
    completedAt:new Date().toISOString(),recordAuthority:'ORIGINAL_SF36_LEDGER_RESULT'};
}

async function main(){
  need(process.argv.length===6&&process.argv[2]==='--context'&&
    process.argv[4]==='--context-sha256','ACCOUNTING_WORKER_ARGUMENTS_INVALID');
  const controller=new AbortController();
  const abort=()=>controller.abort();
  process.once('SIGINT',abort);process.once('SIGTERM',abort);
  try{
    const result=await finalizeSelectedNodeAttempt(process.argv[3],process.argv[5],{signal:controller.signal});
    const raw=jsonBytes(result);
    const context=parseJson((await accountingPrivateFile(process.argv[3],262144)).raw);
    need(raw.length<=context.resultLimit,'ACCOUNTING_RESULT_LIMIT');
    process.stdout.write(raw);
    process.exitCode=result.kind==='UNPAID_RESPONSE'||FINALIZED.has(result.result.outcome)?0:2;
  }finally{
    process.removeListener('SIGINT',abort);process.removeListener('SIGTERM',abort);
  }
}
if(process.argv[1]&&await realpath(process.argv[1]).catch(()=>null)===here)
  main().catch(error=>{process.stderr.write(JSON.stringify({
    error:safeCode(error.code,'ACCOUNTING_WORKER_FAILED')})+'\n');process.exitCode=2;});

// MIT. Durable accounting for one original Node Buyer operation.
import {mkdtemp,readdir,lstat,realpath,readFile,readlink,stat} from 'node:fs/promises';
import {basename,dirname,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {isDeepStrictEqual} from 'node:util';
import {absolute,privateDirectory,digest,now,intent,object,need,BuyerError,
  jsonBytes,parseJson,readBytes,readJson,writeBytes,writeJson,exists,syncDirectory,safeCode} from './store.mjs';

export const OPERATION_ACCOUNTING_COMMAND='stellar-forge.node-operation-accounting-command.v1';
export const OPERATION_ACCOUNTING_NATIVE='stellar-forge.node-operation-accounting-native.v1';
const VIEW='stellar-forge.node-operation-accounting-view.v1';
const EXPORT='stellar-forge.node-operation-accounting-export.v1';
const NODE='stellar-forge.node-buyer.v1';
const HASH=/^[a-f0-9]{64}$/;
const COMMAND=/^finalize-[A-Za-z0-9]{6}$/;
const WORKER=fileURLToPath(new URL('./operation-accounting-worker.mjs',import.meta.url));
const ADAPTER=fileURLToPath(import.meta.url);
const FINALIZED=new Set(['FINALIZED','IDEMPOTENT_FINALIZED']);
const LIMIT=4_194_304;
export const sameAccountingValue=isDeepStrictEqual;
const copy=value=>parseJson(jsonBytes(value));
const checkSignal=signal=>{
  need(signal===undefined||signal instanceof AbortSignal,'INVALID_ABORT_SIGNAL');
  need(!signal?.aborted,'OPERATION_ABORTED_BEFORE_START');
};
const validTime=value=>typeof value==='string'&&Number.isFinite(Date.parse(value));
const frozen=value=>{
  if(value&&typeof value==='object'){for(const child of Object.values(value))frozen(child);Object.freeze(value);}
  return value;
};

export async function accountingPrivateDirectory(path,{create=false}={}){
  const selected=absolute(path);
  need(selected===path,'ACCOUNTING_CANONICAL_PATH_REQUIRED');
  await privateDirectory(selected,{create});
  need(await realpath(selected)===selected,'ACCOUNTING_CANONICAL_PATH_REQUIRED');
  return selected;
}

export async function accountingPrivateFile(path,limit=65536){
  need(absolute(path)===path,'ACCOUNTING_CANONICAL_PATH_REQUIRED');
  await accountingPrivateDirectory(dirname(path));
  const before=await lstat(path);
  need(before.isFile()&&!before.isSymbolicLink()&&(before.mode&0o077)===0&&
    (!process.getuid||before.uid===process.getuid()),'ACCOUNTING_PRIVATE_FILE_REQUIRED');
  const raw=await readBytes(path,limit),after=await lstat(path);
  need(after.isFile()&&!after.isSymbolicLink()&&before.dev===after.dev&&before.ino===after.ino&&
    before.size===after.size&&raw.length===after.size&&before.mtimeMs===after.mtimeMs&&
    before.ctimeMs===after.ctimeMs,'ACCOUNTING_SOURCE_CHANGED_DURING_READ');
  return{raw,descriptor:{path,bytes:raw.length,sha256:digest(raw)}};
}

async function codeFile(path){
  need(absolute(path)===path&&await realpath(path)===path,'ACCOUNTING_SOURCE_PATH_INVALID');
  const info=await lstat(path);
  need(info.isFile()&&(info.mode&0o022)===0,'ACCOUNTING_SOURCE_FILE_INVALID');
  const raw=await readBytes(path,16_777_216);
  return{path,bytes:raw.length,sha256:digest(raw)};
}

function recordedEnd(attempt){
  return ['RECORDED','NATIVE_RESULT_UNAVAILABLE'].includes(attempt.state)&&
    validTime(attempt.endedAt)&&Object.hasOwn(attempt,'exitCode')&&
    (attempt.exitCode===null||Number.isInteger(attempt.exitCode));
}

// Read the original captured identity. This never sends a signal or substitutes
// a current PID for the captured process. Completed native exits remain usable
// when a later container cannot inspect the producer's procfs namespace.
export async function accountingProducerState(attempt){
  const id=attempt.processIdentity;
  let observation={state:'UNKNOWN',basis:'ORIGINAL_PROCESS_IDENTITY_UNAVAILABLE'};
  if(id?.schema==='stellar-forge.node-process-identity.v1'&&id.status==='RECORDED'&&
      Number.isSafeInteger(id.procPid)&&id.procPid>0&&/^[0-9]+$/.test(id.startTicks??'')&&
      /^pid:\[[0-9]+\]$/.test(id.namespace??'')&&typeof id.bootId==='string'&&
      typeof id.procfsDevice==='string'){
    let inspected=false;
    try{
      const boot=(await readFile('/proc/sys/kernel/random/boot_id','utf8')).trim();
      if(boot!==id.bootId)observation={state:'ENDED',basis:'ORIGINAL_BOOT_ENDED'};
      else if((await stat('/proc',{bigint:true})).dev.toString()===id.procfsDevice){
        inspected=true;
        const readStat=async()=>{
          const raw=await readFile('/proc/'+id.procPid+'/stat','utf8');
          const close=raw.lastIndexOf(')'),fields=raw.slice(close+2).trim().split(/\s+/);
          need(close>0&&fields.length>=20,'ACCOUNTING_PROCESS_STAT_INVALID');
          return{state:fields[0],startTicks:fields[19]};
        };
        const first=await readStat();
        if(first.startTicks!==id.startTicks)observation={state:'ENDED',basis:'ORIGINAL_PROCESS_REPLACED'};
        else if(['Z','X'].includes(first.state))observation={state:'ENDED',basis:'ORIGINAL_PROCESS_EXITED'};
        else{
          const namespace=await readlink('/proc/'+id.procPid+'/ns/pid'),last=await readStat();
          if(last.startTicks!==id.startTicks||namespace!==id.namespace)
            observation={state:'ENDED',basis:'ORIGINAL_PROCESS_REPLACED'};
          else observation={state:['Z','X'].includes(last.state)?'ENDED':'LIVE',basis:'CAPTURED_PROCESS_IDENTITY'};
        }
      }
    }catch(error){
      if(inspected&&['ENOENT','ESRCH'].includes(error.code))observation={state:'ENDED',basis:'ORIGINAL_PROCESS_ABSENT'};
      else observation={state:'UNKNOWN',basis:safeCode(error.code,'ORIGINAL_PROCESS_NOT_OBSERVED')};
    }
  }
  if(observation.state==='UNKNOWN'&&recordedEnd(attempt))
    observation={state:'ENDED',basis:'ORIGINAL_NATIVE_EXIT_RECORDED'};
  return observation;
}

/** Reuse the original Operation binding, including its selected preapproval
 * chain. This projection creates no financial record and loads no keys. */
export async function readOperationAccountingSource(operation,{evidence=true,requireEnded=false,signal}={}){
  checkSignal(signal);
  const {meta,config}=await operation._bound();
  await accountingPrivateDirectory(operation.buyer.stateDirectory);
  await accountingPrivateDirectory(operation.directory);
  need(operation.directory===join(operation.buyer.stateDirectory,digest(operation.intentId))&&
    operation.configPath===join(operation.directory,'config.json'),'ACCOUNTING_OPERATION_PATH_CHANGED');
  need(meta.schema===NODE&&meta.state==='PREPARED'&&meta.intentId===operation.intentId&&
    absolute(meta.runtimeDirectory)===meta.runtimeDirectory,'ACCOUNTING_ORIGINAL_OPERATION_REQUIRED');
  let attemptDirectory=operation.directory,preapproval=null;
  if(await exists(join(operation.directory,'preapproval-continuation.json'))){
    preapproval=await operation.readPreapprovalRecovery();
    need(preapproval.pending===null&&preapproval.history.length>0,
      'ACCOUNTING_PREAPPROVAL_ATTEMPT_REQUIRED');
    attemptDirectory=await accountingPrivateDirectory(preapproval.directory);
  }
  const files={};
  for(const [name,path,limit] of [
    ['operation',join(operation.directory,'operation.json'),262144],
    ['configuration',operation.configPath,65536],
    ['attempt',join(attemptDirectory,'attempt.json'),65536],
  ])files[name]=await accountingPrivateFile(path,limit);
  const attempt=parseJson(files.attempt.raw);
  need(sameAccountingValue(meta,parseJson(files.operation.raw))&&
    sameAccountingValue(config,parseJson(files.configuration.raw))&&
    files.configuration.descriptor.sha256===meta.configSha256&&
    attempt.schema===NODE&&attempt.intentId===operation.intentId&&attempt.kind===undefined&&
    attempt.configSha256===meta.configSha256&&attempt.bodySha256===meta.bodySha256&&
    validTime(attempt.createdAt)&&
    ['STARTING','STARTED','RECORDED','INTERRUPTED_OR_START_FAILED','NATIVE_RESULT_UNAVAILABLE'].includes(attempt.state),
    'ACCOUNTING_ORIGINAL_ATTEMPT_REQUIRED');
  const bodyPresent=config.operation.bodyFile!==undefined;
  let body=Buffer.alloc(0),bodyFile=null,ticketFile=null;
  if(bodyPresent){
    need(config.operation.bodyFile===join(operation.directory,'request.body'),
      'ACCOUNTING_REQUEST_BODY_PATH_CHANGED');
    const reader=await operation.buyer._requestFiles();
    bodyFile=await accountingPrivateFile(config.operation.bodyFile,reader.MAX_REQUEST_BODY_BYTES);
    body=bodyFile.raw;
  }
  need(digest(body)===meta.bodySha256,'ACCOUNTING_REQUEST_BODY_CHANGED');
  if(config.operation.ticketFile!==undefined){
    need(config.operation.ticketFile===join(operation.directory,'operation-ticket.json'),
      'ACCOUNTING_TICKET_PATH_CHANGED');
    ticketFile=await accountingPrivateFile(config.operation.ticketFile,16384);
  }
  need((ticketFile?.descriptor.sha256??null)===(meta.ticketSha256??null),'ACCOUNTING_TICKET_CHANGED');
  let commandSha256=null;
  if(attempt.nativeCommand!==undefined){
    need(object(attempt.nativeCommand)&&Array.isArray(attempt.nativeCommand.command)&&
      attempt.nativeCommand.command.every(v=>typeof v==='string')&&
      digest(jsonBytes(attempt.nativeCommand.command))===attempt.nativeCommand.commandSha256,
      'ACCOUNTING_PRODUCING_COMMAND_CHANGED');
    commandSha256=attempt.nativeCommand.commandSha256;
  }
  const producer=await accountingProducerState(attempt);
  if(requireEnded)need(producer.state==='ENDED',
    producer.state==='LIVE'?'ACCOUNTING_PRODUCING_ATTEMPT_LIVE':'ACCOUNTING_PRODUCER_STATE_UNAVAILABLE');
  const nativeWorkspace=meta.nativeWorkspace??null;
  if(nativeWorkspace===null)
    need(config.evidenceDir===join(operation.directory,'evidence'),'ACCOUNTING_EVIDENCE_PATH_CHANGED');
  const evidencePath=join(await accountingPrivateDirectory(config.evidenceDir),digest(operation.intentId)+'.json');
  const retained=evidence?await accountingPrivateFile(evidencePath,LIMIT):null;
  const identity={
    intentId:operation.intentId,stateDirectory:operation.buyer.stateDirectory,
    operationDirectory:operation.directory,producerRuntimeDirectory:meta.runtimeDirectory,
    operationSha256:files.operation.descriptor.sha256,configurationSha256:meta.configSha256,
    bodyPresent,bodyBytes:body.length,bodySha256:meta.bodySha256,ticketSha256:meta.ticketSha256??null,
    attemptDirectory,attemptCreatedAt:attempt.createdAt,producingCommandSha256:commandSha256,
    nativeWorkspace,preapprovalHistorySha256:preapproval?digest(jsonBytes(preapproval.history)):null,
  };
  checkSignal(signal);
  return{identity,meta,config,attempt,body,producer,evidencePath,
    files:{...Object.fromEntries(Object.entries(files).map(([key,value])=>[key,value.descriptor])),
      body:bodyFile?.descriptor??null,ticket:ticketFile?.descriptor??null,
      evidence:retained?.descriptor??null},
    attemptRaw:files.attempt.raw,evidenceRaw:retained?.raw??null};
}

function finalizeOptions(options,source){
  need(object(options)&&Object.keys(options).every(key=>
    ['workspaceDirectory','outboxDirectory','merchantRoute','signal'].includes(key)),
    'ACCOUNTING_OPTIONS_INVALID');
  checkSignal(options.signal);
  const chosen=options.workspaceDirectory??source.identity.nativeWorkspace;
  need(chosen===null||typeof chosen==='string','ACCOUNTING_ORIGINAL_WORKSPACE_REQUIRED');
  const workspaceDirectory=chosen===null?null:absolute(chosen);
  need(chosen===workspaceDirectory&&
    (source.identity.nativeWorkspace===null||workspaceDirectory===source.identity.nativeWorkspace),
    'ACCOUNTING_ORIGINAL_WORKSPACE_CHANGED');
  need((options.outboxDirectory!==undefined)===(options.merchantRoute!==undefined),
    'OUTBOX_AND_ORIGINAL_MERCHANT_ROUTE_REQUIRED_TOGETHER');
  if(options.merchantRoute!==undefined)need(typeof options.merchantRoute==='string'&&
    /^[A-Za-z0-9_-]{1,80}$/.test(options.merchantRoute),'ACCOUNTING_MERCHANT_ROUTE_INVALID');
  return{workspaceDirectory,outboxDirectory:options.outboxDirectory===undefined?null:absolute(options.outboxDirectory),
    merchantRoute:options.merchantRoute??null};
}

export function accountingOutput(context,output){
  need(output?.schema===OPERATION_ACCOUNTING_NATIVE&&
    output.contextSha256===digest(jsonBytes(context))&&
    sameAccountingValue(output.identity,context.identity)&&
    output.workspace===context.request.workspaceDirectory&&
    output.accountingRuntimeDirectory===context.execution.runtimeDirectory&&
    output.evidenceSha256===context.source.evidence.sha256&&
    output.attemptSnapshotSha256===context.source.attempt.sha256&&validTime(output.completedAt)&&
    sameAccountingValue(output.workspaceSource,context.workspaceSource),
    'ACCOUNTING_NATIVE_BINDING_CHANGED');
  if(output.kind==='PAID_FINALIZATION'){
    need(output.result?.schema==='stellar-forge.sf36.finalization.v1'&&
      ['FINALIZED','IDEMPOTENT_FINALIZED','NOT_FINALIZED','WORKER_ERROR'].includes(output.result.outcome)&&
      HASH.test(output.approvedRequestSha256??''),'ACCOUNTING_ORIGINAL_FINALITY_RESULT_REQUIRED');
    if(FINALIZED.has(output.result.outcome))need(output.result.request_id===context.identity.intentId&&
      output.result.request_sha256===output.approvedRequestSha256,'ACCOUNTING_FINALIZED_REQUEST_CHANGED');
  }else need(output.kind==='UNPAID_RESPONSE'&&output.result?.outcome==='NO_PAYMENT_REQUIRED'&&
    output.approvedRequestSha256===null,'ACCOUNTING_ORIGINAL_UNPAID_RESULT_REQUIRED');
  return copy(output);
}
function returned(context,output,process,extra={}){
  return{native:accountingOutput(context,output),commandId:context.commandId,
    commandDirectory:context.commandDirectory,startedAt:context.startedAt,process:copy(process),...extra};
}

async function commandSource(directory,context){
  const savedAttempt=await accountingPrivateFile(join(directory,'attempt-source.json'),65536);
  const savedEvidence=await accountingPrivateFile(join(directory,'evidence-source.json'),LIMIT);
  need(savedAttempt.descriptor.sha256===context.source.attempt.sha256&&
    savedEvidence.descriptor.sha256===context.source.evidence.sha256,'ACCOUNTING_ARCHIVED_SOURCE_CHANGED');
  return{attempt:savedAttempt,evidence:savedEvidence};
}

export async function finalizeOperationAccounting(operation,options={}){
  need(object(options),'ACCOUNTING_OPTIONS_INVALID');
  const source=await readOperationAccountingSource(operation,{requireEnded:true,signal:options.signal});
  const request=finalizeOptions(options,source);
  if(request.workspaceDirectory!==null)await accountingPrivateDirectory(request.workspaceDirectory);
  if(request.outboxDirectory!==null)await accountingPrivateDirectory(request.outboxDirectory);
  const workspaceSource=request.workspaceDirectory===null?null:{};
  if(workspaceSource)for(const [key,name] of [['configuration','operator.json'],['manifest','workspace.json']])
    workspaceSource[key]=(await accountingPrivateFile(join(request.workspaceDirectory,name))).descriptor;
  const runtime=operation.buyer.runtime;
  const execution={runtimeDirectory:absolute(runtime.directory),node:absolute(runtime.node),
    adapter:await codeFile(ADAPTER),worker:await codeFile(WORKER),originalSource:[]};
  need(await realpath(execution.runtimeDirectory)===execution.runtimeDirectory,
    'ACCOUNTING_RUNTIME_CANONICAL_PATH_REQUIRED');
  for(const name of ['config.mjs','workspace.mjs','finalization.mjs',
    '../sf36-spend-governor/finalize.py','../sf86-rpc-transfer-reconcile/cli.mjs',
    '../sf86-rpc-transfer-reconcile/terms.mjs'])
    execution.originalSource.push(await codeFile(absolute(join(execution.runtimeDirectory,name))));
  const parent=await accountingPrivateDirectory(join(operation.directory,'accounting'),{create:true});
  const directory=await mkdtemp(join(parent,'finalize-'));
  const context={schema:OPERATION_ACCOUNTING_COMMAND,commandId:basename(directory),
    commandDirectory:directory,startedAt:now(),identity:source.identity,
    source:source.files,request,workspaceSource,execution,
    resultLimit:Math.min(runtime.outputLimit,LIMIT)};
  need(context.resultLimit>=65536,'ACCOUNTING_RUNTIME_OUTPUT_LIMIT_TOO_SMALL');
  await writeBytes(join(directory,'attempt-source.json'),source.attemptRaw,{exclusive:true});
  await writeBytes(join(directory,'evidence-source.json'),source.evidenceRaw,{exclusive:true});
  await writeJson(join(directory,'context.json'),context,{exclusive:true});
  await syncDirectory(parent);
  const contextSha256=digest(jsonBytes(context));
  let run;
  try{
    run=await runtime.run(['--context',join(directory,'context.json'),'--context-sha256',contextSha256],{
      directory,entryFile:WORKER,signal:options.signal,
      beforeSpawn:async invocation=>writeJson(join(directory,'invocation.json'),invocation,{exclusive:true}),
      started:async(pid,processIdentity)=>writeJson(join(directory,'process.json'),
        {pid,processIdentity,startedAt:now()},{exclusive:true}),
    });
  }catch(error){
    run={output:null,exitCode:null,exitSignal:null,
      errorCode:safeCode(error.code,'ACCOUNTING_PROCESS_RESULT_UNAVAILABLE')};
  }
  const process={exitCode:run.exitCode,exitSignal:run.exitSignal,errorCode:run.errorCode};
  let result=null;
  try{if(run.output)result=returned(context,run.output,process);}
  catch(error){process.errorCode=safeCode(error.code,'ACCOUNTING_NATIVE_BINDING_CHANGED');}
  let viewStatus='SAVED';
  try{
    await writeJson(join(directory,'completion.json'),{schema:OPERATION_ACCOUNTING_COMMAND,
      contextSha256,completedAt:now(),process,output:result?run.output:null},{exclusive:true});
  }catch{viewStatus='SAVE_FAILED';}
  if(!result)throw new BuyerError(process.errorCode??'ACCOUNTING_NATIVE_RESULT_UNAVAILABLE',
    {operation,commandId:context.commandId,commandDirectory:directory,exitCode:process.exitCode});
  const value=frozen({...result,viewStatus,recovered:false});
  operation.lastAccounting=value;
  return value;
}

async function readCommand(operation,identity,name){
  need(typeof name==='string'&&COMMAND.test(name),'ACCOUNTING_COMMAND_ID_INVALID');
  const directory=await accountingPrivateDirectory(join(operation.directory,'accounting',name));
  const raw=await accountingPrivateFile(join(directory,'context.json'),262144);
  const context=parseJson(raw.raw);
  need(context.schema===OPERATION_ACCOUNTING_COMMAND&&context.commandId===name&&
    context.commandDirectory===directory&&sameAccountingValue(context.identity,identity)&&
    validTime(context.startedAt)&&context.resultLimit>=65536&&context.resultLimit<=LIMIT&&
    Number.isSafeInteger(context.resultLimit),'ACCOUNTING_COMMAND_BINDING_CHANGED');
  need(digest(jsonBytes(context))===raw.descriptor.sha256,'ACCOUNTING_CONTEXT_SERIALIZATION_CHANGED');
  await commandSource(directory,context);
  let process={exitCode:null,exitSignal:null,errorCode:'PROCESS_EXIT_NOT_RECORDED'};
  let result=null,status='NO_COMPLETE_OUTPUT';
  if(await exists(join(directory,'completion.json'))){
    const completed=await readJson(join(directory,'completion.json'),context.resultLimit+262144);
    need(completed.schema===OPERATION_ACCOUNTING_COMMAND&&
      completed.contextSha256===raw.descriptor.sha256&&object(completed.process),
      'ACCOUNTING_COMPLETION_CHANGED');
    process=completed.process;
    if(completed.output){
      result=returned(context,completed.output,process,{viewStatus:'SAVED',recovered:false});
      status='RECORDED';
    }
  }
  if(!result){
    let output;
    try{output=await readJson(join(directory,'stdout.json'),context.resultLimit);}
    catch(error){
      if(!['ENOENT','JSON_INVALID','JSON_OBJECT_REQUIRED','FILE_SIZE_OR_TYPE_INVALID'].includes(error.code))throw error;
    }
    if(output){
      result=returned(context,output,process,{viewStatus:'RECOVERED_NATIVE_OUTPUT',recovered:true});
      status='OUTPUT_RECOVERED';
    }
  }
  return{commandId:name,commandDirectory:directory,startedAt:context.startedAt,status,process,result};
}

/** Pure local reopening. No key loader, RPC, finalizer or buyer is invoked. */
export async function recoverOperationAccounting(operation,{commandId}={}){
  const {identity}=await readOperationAccountingSource(operation,{evidence:false});
  const parent=join(operation.directory,'accounting');
  if(!await exists(parent))return null;
  await accountingPrivateDirectory(parent);
  if(commandId!==undefined){
    const latest=await readCommand(operation,identity,commandId);
    return frozen({schema:VIEW,intentId:operation.intentId,latest,lastComplete:latest.result,
      lastFinalized:FINALIZED.has(latest.result?.native.result?.outcome)?latest.result:null});
  }
  const choices=[];
  for(const row of await readdir(parent,{withFileTypes:true})){
    if(!row.isDirectory()||!COMMAND.test(row.name)||
      !await exists(join(parent,row.name,'context.json')))continue;
    const context=await readJson(join(parent,row.name,'context.json'),262144);
    need(validTime(context.startedAt),'ACCOUNTING_COMMAND_TIME_INVALID');
    choices.push({name:row.name,startedAt:context.startedAt});
  }
  choices.sort((a,b)=>b.startedAt.localeCompare(a.startedAt)||b.name.localeCompare(a.name));
  if(!choices.length)return null;
  const latest=await readCommand(operation,identity,choices[0].name);
  let lastComplete=latest.result;
  let lastFinalized=FINALIZED.has(latest.result?.native.result?.outcome)?latest.result:null;
  for(let index=1;index<choices.length&&(!lastComplete||!lastFinalized);index++){
    const selected=await readCommand(operation,identity,choices[index].name);
    lastComplete??=selected.result;
    if(FINALIZED.has(selected.result?.native.result?.outcome))lastFinalized??=selected.result;
  }
  return frozen({schema:VIEW,intentId:operation.intentId,latest,lastComplete,lastFinalized});
}

/** Export the complete selected native accounting view and its exact retained
 * attempt/evidence bytes. The original ledger and keys remain in their workspace. */
export async function exportOperationAccounting(operation,destination,{commandId,signal}={}){
  checkSignal(signal);
  destination=absolute(destination);
  await accountingPrivateDirectory(dirname(destination));
  const view=await recoverOperationAccounting(operation,{commandId});
  const result=commandId===undefined?view?.lastComplete:view?.latest.result;
  need(result,'ACCOUNTING_COMPLETE_OUTPUT_REQUIRED');
  const directory=result.commandDirectory;
  const contextFile=await accountingPrivateFile(join(directory,'context.json'),262144);
  const context=parseJson(contextFile.raw),sources=await commandSource(directory,context);
  const value={schema:EXPORT,intentId:operation.intentId,commandId:result.commandId,
    context,contextSha256:contextFile.descriptor.sha256,result,
    source:{attempt:{sha256:sources.attempt.descriptor.sha256,
      bytes:sources.attempt.raw.length,base64:sources.attempt.raw.toString('base64')},
      evidence:{sha256:sources.evidence.descriptor.sha256,
      bytes:sources.evidence.raw.length,base64:sources.evidence.raw.toString('base64')}},
    authority:'ORIGINAL_SF36_RESULT_AND_RETAINED_ORIGINAL_ATTEMPT'};
  const bytes=jsonBytes(value);
  checkSignal(signal);
  await writeBytes(destination,bytes,{exclusive:true});
  return frozen({path:destination,bytes:bytes.length,sha256:digest(bytes),format:'json',
    intentId:operation.intentId,commandId:result.commandId,outcome:result.native.result.outcome});
}

// MIT. Explicit continuation of the same original intent before any reservation.
// The original execute marker is retained. SF36/SF62/SF81 still own approval,
// reservation, signing and payment; this module owns only linked local attempts.
import { spawn } from 'node:child_process';
import { constants } from 'node:fs';
import { open, lstat, mkdtemp, rm, rename } from 'node:fs/promises';
import { dirname, basename, join } from 'node:path';
import { pathToFileURL, fileURLToPath } from 'node:url';
import { absolute, privateDirectory, readJson, readBytes, parseJson, writeJson, writeBytes,
  syncDirectory, jsonBytes, digest, now, object, need, BuyerError, exists, prepareWriteReservations } from './store.mjs';
import { checkWorkspace, workspaceCommand } from './workspace.mjs';
import { unstartedAttempt, resultRecordLimit, attemptRecordLimit } from './runtime.mjs';
import { inspectPreapprovalWireCheckpoint, readPreapprovalWireHistory,
  withPreapprovalWireHistory } from '../attempt-wire.mjs';

const SCHEMA = 'stellar-forge.node-preapproval-recovery.v1';
const NODE_SCHEMA = 'stellar-forge.node-buyer.v1';
const NATIVE_RESULT = 'ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT';
const PROOF_SCHEMA = 'stellar-forge.node-preapproval-process-proof.v1';
const PROOF = fileURLToPath(new URL('./preapproval-native-record.py', import.meta.url));
const HASH = /^[a-f0-9]{64}$/;
const LIMIT = 1048576;
const copy = value => JSON.parse(jsonBytes(value));
const checkSignal = signal => {
  need(signal === undefined || signal instanceof AbortSignal, 'INVALID_ABORT_SIGNAL');
  need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
};
const details = ({ raw, ...value }) => value;


async function wireInput(operation,current) {
  const body=current.config.operation.bodyFile===undefined?undefined:
    await (await operation.buyer._requestFiles()).readRequestFile(current.config.operation.bodyFile);
  need(digest(body??Buffer.alloc(0))===current.meta.bodySha256,'PREAPPROVAL_CONFIGURATION_CHANGED');
  return {cfg:current.config,body};
}
async function selectedWireHistory(operation,current,entry) {
  return readPreapprovalWireHistory({...await wireInput(operation,current),
    historyDirectory:entry.directory,planSha256:entry.planSha256,
    sourceAttemptSha256:entry.sourceAttemptSha256,expectedCheckpoint:entry.plan.wireCheckpoint});
}

async function snapshot(name, path, { limit = LIMIT, optional = false } = {}) {
  path = absolute(path);
  let fd;
  try { fd = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0)); }
  catch (error) {
    if (optional && error.code === 'ENOENT') return { name, path, exists: false };
    throw error;
  }
  try {
    const before = await fd.stat();
    need(before.isFile() && before.nlink === 1 && before.size <= limit &&
      (process.platform === 'win32' || (before.mode & 0o077) === 0 &&
        before.uid === process.getuid()), 'PREAPPROVAL_PRIVATE_SOURCE_REQUIRED');
    const raw = await fd.readFile();
    const after = await fd.stat(), current = await lstat(path);
    need(raw.length === before.size && before.dev === after.dev && before.ino === after.ino &&
      after.size === before.size && current.dev === after.dev && current.ino === after.ino &&
      !current.isSymbolicLink(), 'PREAPPROVAL_SOURCE_CHANGED');
    return { name, path, exists: true, bytes: raw.length, sha256: digest(raw),
      device: before.dev, inode: before.ino, raw };
  } finally { await fd.close(); }
}

function validPlan(plan, operation, directory) {
  need(plan?.schema === SCHEMA && plan.intentId === operation.intentId &&
    plan.operationDirectory === operation.directory && plan.directory === directory &&
    HASH.test(plan.sourceAttemptSha256 ?? '') && HASH.test(plan.configSha256 ?? '') &&
    HASH.test(plan.reviewSha256 ?? '') && Array.isArray(plan.sources) &&
    plan.sources.length >= 7 && plan.sources.length <= 12 &&
    (plan.wireCheckpoint===undefined || object(plan.wireCheckpoint) &&
      plan.wireCheckpoint.schema==='stellar-forge.sf88.preapproval-wire.v1.checkpoint' &&
      HASH.test(plan.wireCheckpoint.sha256??'')) &&
    plan.directory === join(operation.directory, 'preapproval-history', plan.sourceAttemptSha256) &&
    (plan.sourceDirectory === operation.directory ||
      dirname(plan.sourceDirectory) === join(operation.directory, 'preapproval-history') &&
      HASH.test(basename(plan.sourceDirectory))) &&
    new Set(plan.sources.map(value => value.name)).size === plan.sources.length &&
    plan.sources.every(value => object(value) &&
      ['operation.json', 'config.json', 'review.json', 'attempt.json', 'stdout.json',
        'stderr.log', 'download-reservation.json', 'partial.bin'].includes(value.name) &&
      typeof value.path === 'string' && typeof value.exists === 'boolean' &&
      (!value.exists || HASH.test(value.sha256 ?? '') && Number.isSafeInteger(value.bytes) && value.bytes >= 0)),
  'PREAPPROVAL_HISTORY_INVALID');
  return plan;
}

async function chain(operation) {
  const { meta, config } = await operation._bound();
  let directory = operation.directory;
  const history = [], seen = new Set();
  for (let depth = 0; depth < 64; depth++) {
    const attemptPath = join(directory, 'attempt.json');
    const attempt = await exists(attemptPath) ? await readJson(attemptPath, attemptRecordLimit) : null;
    if (attempt) {
      need(attempt.schema === NODE_SCHEMA && attempt.intentId === operation.intentId &&
        attempt.configSha256 === meta.configSha256 && attempt.bodySha256 === meta.bodySha256,
      'PREAPPROVAL_ATTEMPT_BINDING_CHANGED');
      if (history.length) need(attempt.preapprovalRecovery?.planSha256 === history.at(-1).planSha256 &&
        attempt.preapprovalRecovery?.sourceAttemptSha256 === history.at(-1).sourceAttemptSha256,
      'PREAPPROVAL_ATTEMPT_LINEAGE_CHANGED');
    }
    const linkPath = join(directory, 'preapproval-continuation.json');
    if (!await exists(linkPath)) return { meta, config, directory, attempt, history,
      pending: history.length && !attempt ? history.at(-1) : null };
    need(attempt && attempt.intentId === operation.intentId &&
      attempt.configSha256 === meta.configSha256, 'PREAPPROVAL_ATTEMPT_BINDING_CHANGED');
    const link = await readJson(linkPath, 16384);
    const raw = await readBytes(attemptPath, attemptRecordLimit);
    need(link.schema === SCHEMA && link.intentId === operation.intentId &&
      link.sourceAttemptSha256 === digest(raw) && HASH.test(link.planSha256 ?? '') &&
      link.directory === join(operation.directory, 'preapproval-history', link.sourceAttemptSha256) &&
      !seen.has(link.directory), 'PREAPPROVAL_LINEAGE_CHANGED');
    seen.add(link.directory);
    const planRaw = await readBytes(join(link.directory, 'plan.json'), 262144);
    need(digest(planRaw) === link.planSha256, 'PREAPPROVAL_PLAN_CHANGED');
    const plan = validPlan(parseJson(planRaw), operation, link.directory);
    need(plan.sourceDirectory === directory && plan.sourceAttemptSha256 === link.sourceAttemptSha256 &&
      plan.configSha256 === meta.configSha256 && plan.bodySha256 === meta.bodySha256 &&
      (plan.ticketSha256 ?? null) === (meta.ticketSha256 ?? null),
    'PREAPPROVAL_CONFIGURATION_CHANGED');
    await verifyArchive(plan);
    const wireHistory=await selectedWireHistory(operation,{meta,config},{...link,plan});
    if(await exists(join(link.directory,'attempt.json')) && plan.wireCheckpoint!==undefined)
      need(wireHistory?.status==='RETAINED','PREAPPROVAL_WIRE_RETIREMENT_REQUIRED');
    history.push({ ...link, plan, wireHistory });
    directory = link.directory;
    await privateDirectory(directory, { create: false });
  }
  throw new BuyerError('PREAPPROVAL_HISTORY_LIMIT');
}

async function readSources(operation, current, retainedPlan = null) {
  const { meta, config, directory, attempt } = current;
  need(typeof meta.nativeWorkspace === 'string', 'PREAPPROVAL_ORIGINAL_WORKSPACE_REQUIRED');
  need(attempt?.schema === NODE_SCHEMA && attempt.intentId === operation.intentId &&
    attempt.configSha256 === meta.configSha256 && attempt.bodySha256 === meta.bodySha256 &&
    attempt.kind !== 'INBOX_DELEGATED', 'PREAPPROVAL_ORIGINAL_ATTEMPT_REQUIRED');
  need(!await exists(join(directory, 'result.json')), 'PREAPPROVAL_RESULT_ALREADY_RECORDED');
  const destination = absolute(config.responseFile?.destination);
  const evidencePath = join(absolute(config.evidenceDir), digest(operation.intentId) + '.json');
  need(!await exists(destination) && !await exists(evidencePath),
    'PREAPPROVAL_ORIGINAL_OUTPUT_EXISTS');
  const reviewPath = join(directory, 'review.json');
  const reservationPath = join(dirname(destination), '.' + basename(destination) + '.x402-download.lock');
  const released = retainedPlan ? join(retainedPlan.directory, 'released-download-reservation.json') : null;
  const originalReservation = released && await exists(released) ? released : reservationPath;
  if (originalReservation !== reservationPath)
    need(!await exists(reservationPath), 'PREAPPROVAL_NEW_OUTPUT_WRITER_EXISTS');
  const sources = await Promise.all([
    snapshot('operation.json', join(operation.directory, 'operation.json'), { limit: 65536 }),
    snapshot('config.json', operation.configPath, { limit: 65536 }),
    snapshot('review.json', reviewPath, { limit: 262144 }),
    snapshot('attempt.json', join(directory, 'attempt.json'), { limit: attemptRecordLimit }),
    snapshot('stdout.json', join(directory, 'stdout.json'), { optional: true }),
    snapshot('stderr.log', join(directory, 'stderr.log'), { optional: true }),
    snapshot('download-reservation.json', originalReservation, { optional: true, limit: 16384 }),
  ]);
  need(sources[1].sha256 === meta.configSha256, 'PREAPPROVAL_CONFIGURATION_CHANGED');
  need(!sources[4].exists || sources[4].bytes === 0, 'PREAPPROVAL_NATIVE_OUTPUT_EXISTS');
  need(!sources[5].exists || sources[5].bytes === 0, 'PREAPPROVAL_NATIVE_OUTPUT_EXISTS');
  const reviewed = parseJson(sources[2].raw);
  need(reviewed.intentId === operation.intentId && reviewed.configSha256 === meta.configSha256 &&
    reviewed.bodySha256 === meta.bodySha256 &&
    (reviewed.nativeWorkspace ?? null) === (meta.nativeWorkspace ?? null),
  'PREAPPROVAL_REVIEW_BINDING_CHANGED');
  const reservation = sources[6];
  if (reservation.exists) {
    const held = parseJson(reservation.raw);
    need(held.destination === destination && held.pid === attempt.pid &&
      typeof held.partialPath === 'string' && dirname(absolute(held.partialPath)) === dirname(destination) &&
      /^\.x402-response-[a-f0-9-]+\.partial$/.test(basename(held.partialPath)),
    'PREAPPROVAL_DOWNLOAD_RESERVATION_CHANGED');
    const partial = await snapshot('partial.bin', held.partialPath, { limit: 0 });
    need(partial.bytes === 0, 'PREAPPROVAL_PARTIAL_RESPONSE_EXISTS');
    sources.push(partial);
  }
  return sources;
}

async function verifySources(plan) {
  for (const pin of plan.sources) {
    const archived = typeof plan.directory === 'string' && pin.name === 'download-reservation.json'
      ? join(plan.directory, 'released-download-reservation.json') : null;
    const moved = archived && await exists(archived);
    if (moved) need(!await exists(pin.path), 'PREAPPROVAL_NEW_OUTPUT_WRITER_EXISTS');
    const actual = await snapshot(pin.name, moved ? archived : pin.path,
      { optional: !pin.exists, limit: Math.max(pin.bytes ?? 0, 16384) });
    need(actual.exists === pin.exists && (!pin.exists ||
      actual.sha256 === pin.sha256 && actual.bytes === pin.bytes &&
      actual.device === pin.device && actual.inode === pin.inode), 'PREAPPROVAL_SOURCE_CHANGED');
  }
}

async function verifyArchive(plan) {
  for (const pin of plan.sources) {
    if (!pin.exists) continue;
    const raw = await readBytes(join(plan.directory, 'original', pin.name), Math.max(pin.bytes, 1));
    need(raw.length === pin.bytes && digest(raw) === pin.sha256, 'PREAPPROVAL_ARCHIVE_CHANGED');
  }
  const reviewRaw = await readBytes(join(plan.directory, 'review.json'), 262144);
  need(digest(reviewRaw) === plan.reviewSha256 &&
    digest(jsonBytes(plan.review)) === plan.reviewSha256, 'PREAPPROVAL_REVIEW_CHANGED');
  const requestRaw = await readBytes(join(plan.directory, 'process-request.json'), 262144);
  need(digest(requestRaw) === digest(jsonBytes(plan.processRequest)), 'PREAPPROVAL_PROCESS_REQUEST_CHANGED');
}

async function processProof(operation, current, sources, nativeRecord, signal) {
  checkSignal(signal);
  const byName = Object.fromEntries(sources.map(value => [value.name, value]));
  const request = {
    schema: 'stellar-forge.node-preapproval-process-proof-request.v1',
    intentId: operation.intentId, operationDirectory: operation.directory,
    operationPath: byName['operation.json'].path, configPath: operation.configPath,
    reviewPath: byName['review.json'].path, attemptPath: byName['attempt.json'].path,
    nativeWorkspace: current.meta.nativeWorkspace ?? null,
    expected: Object.fromEntries(['operation', 'config', 'review', 'attempt'].map(name =>
      [name + 'Sha256', byName[name + '.json'].sha256])),
    ...(nativeRecord === undefined ? {} : { nativeRecord: copy(nativeRecord) }),
    ...(current.attempt?.processIdentity ? { processIdentity: copy(current.attempt.processIdentity) } : {}),
  };
  const temporary = await mkdtemp(join(operation.buyer.stateDirectory, '.preapproval-inspect-'));
  const path = join(temporary, 'request.json');
  try {
    await writeJson(path, request, { exclusive: true });
    const proof = await new Promise((resolveProof, reject) => {
      let child, done = false, size = 0, timer, cancel;
      const chunks = [];
      const finish = (error, value) => {
        if (done) return; done = true; clearTimeout(timer);
        if (cancel) signal?.removeEventListener('abort', cancel);
        error ? reject(error) : resolveProof(value);
      };
      const abort = () => { child?.kill('SIGKILL'); };
      try {
        child = spawn(absolute(current.config.operator.python), ['-I', '-B', PROOF, '--request', path], {
          env: { LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' }, shell: false, stdio: ['ignore', 'pipe', 'ignore'],
        });
      } catch { return finish(new BuyerError('PREAPPROVAL_PROCESS_INSPECTION_START_FAILED')); }
      let interrupted = false;
      cancel = () => { interrupted = true; abort(); };
      signal?.addEventListener('abort', cancel, { once: true });
      if (signal?.aborted) cancel();
      timer = setTimeout(() => { interrupted = true; abort(); }, 30000);
      child.once('error', () => finish(new BuyerError('PREAPPROVAL_PROCESS_INSPECTION_START_FAILED')));
      child.stdout.on('data', raw => {
        size += raw.length;
        if (size > 65536) { interrupted = true; abort(); }
        else chunks.push(raw);
      });
      child.once('close', code => {
        signal?.removeEventListener('abort', cancel);
        if (done) return;
        if (interrupted) return finish(new BuyerError(signal?.aborted
          ? 'OPERATION_ABORTED_BEFORE_START' : 'PREAPPROVAL_PROCESS_INSPECTION_LIMIT'));
        try {
          const value = parseJson(Buffer.concat(chunks));
          if (code !== 0) throw new BuyerError(/^[A-Z0-9_]{1,120}$/.test(value.code ?? '')
            ? value.code : 'PREAPPROVAL_PROCESS_NOT_PROVEN_ABSENT');
          need(value.schema === PROOF_SCHEMA &&
            value.outcome === 'ORIGINAL_ATTEMPT_PROCESS_ABSENT' &&
            value.intentId === operation.intentId && value.configSha256 === current.meta.configSha256 &&
            value.attemptSha256 === byName['attempt.json'].sha256, 'PREAPPROVAL_PROCESS_NOT_PROVEN_ABSENT');
          finish(null, value);
        } catch (error) { finish(error instanceof BuyerError ? error : new BuyerError('PREAPPROVAL_PROCESS_PROOF_INVALID')); }
      });
    });
    return { request, proof };
  } finally { await rm(temporary, { recursive: true, force: true }); }
}

async function ledgerProof(operation, current, signal) {
  const { meta, config } = current;
  let environment = operation.buyer.runtime.environment;
  if (meta.nativeWorkspace) {
    const context = { directory: meta.nativeWorkspace, configPath: operation.configPath,
      ticketSha256: meta.ticketSha256 ?? null };
    await checkWorkspace(operation.buyer, context, { intentId: operation.intentId, signal });
    const original = await import(pathToFileURL(join(operation.buyer.runtime.directory, 'workspace.mjs')).href);
    const opened = await original.openWorkspace(['--dir', meta.nativeWorkspace], { accounting: true, environment });
    need(opened.config.operator.ledger === config.operator.ledger &&
      opened.config.operator.policy === config.operator.policy &&
      opened.config.operator.actor === config.operator.actor &&
      opened.config.operator.service === config.operator.service, 'PREAPPROVAL_ORIGINAL_OPERATOR_CHANGED');
    environment = opened.operatorEnvironment;
  }
  const original = await import(pathToFileURL(join(operation.buyer.runtime.directory, 'dataset-unpaid.mjs')).href);
  need(typeof original.inspectOriginalUnpaidLedger === 'function', 'PREAPPROVAL_ORIGINAL_LEDGER_INSPECTOR_REQUIRED');
  return original.inspectOriginalUnpaidLedger(config, operation.configPath, meta.configSha256, environment, signal);
}

function preparedView(entry) {
  const { plan } = entry;
  return { schema: SCHEMA, intentId: plan.intentId, status: 'PREPARED',
    directory: plan.directory, attemptSha256: plan.sourceAttemptSha256,
    planSha256: entry.planSha256, review: copy(plan.review),
    originalLedgerCheck: copy(plan.originalLedgerCheck), processProof: copy(plan.processProof),
    ...(entry.wireHistory?{wireHistory:copy(entry.wireHistory)}:{}),
    ...(plan.wireCheckpoint?{originalWire:copy(plan.wireCheckpoint)}:{}) };
}

export async function readPreapprovalRecovery(operation) {
  const current = await chain(operation);
  return { schema: SCHEMA, intentId: operation.intentId,
    state: current.attempt?.state ?? (current.pending ? 'PREAPPROVAL_RECOVERY_PREPARED' : current.meta.state),
    directory: current.directory, history: current.history.map(entry => ({
      directory: entry.directory, planSha256: entry.planSha256,
      attemptSha256: entry.sourceAttemptSha256, reason: entry.plan.reason, createdAt: entry.plan.createdAt,
      ...(entry.wireHistory?{wireHistory:copy(entry.wireHistory)}:{}),
    })), pending: current.pending ? preparedView(current.pending) : null };
}

/** Ordinary review follows the selected immutable continuation instead of rewriting its source. */
export async function readSelectedPreapprovalReview(operation) {
  const current = await chain(operation), selected = current.history.at(-1);
  need(selected, 'PREAPPROVAL_PREPARED_PLAN_REQUIRED');
  return copy(selected.plan.review);
}

export async function inspectPreapprovalRecovery(operation, { nativeRecord, signal } = {}) {
  checkSignal(signal);
  const current = await chain(operation);
  if (current.pending) return preparedView(current.pending);
  const sources = await readSources(operation, current);
  const checked = await processProof(operation, current, sources, nativeRecord, signal);
  const originalLedgerCheck = await ledgerProof(operation, current, signal);
  const originalWire=await inspectPreapprovalWireCheckpoint(await wireInput(operation,current));
  const provisional = { sources: sources.map(details) };
  await verifySources(provisional);
  return { schema: SCHEMA, intentId: operation.intentId, status: 'AVAILABLE',
    attemptSha256: sources.find(value => value.name === 'attempt.json').sha256,
    configSha256: current.meta.configSha256, directory: current.directory,
    sources: provisional.sources, processProof: checked.proof, originalLedgerCheck, originalWire };
}

export async function preparePreapprovalRecovery(operation,
  { expectedAttemptSha256, nativeRecord, reason, signal } = {}) {
  checkSignal(signal);
  need(HASH.test(expectedAttemptSha256 ?? ''), 'PREAPPROVAL_ATTEMPT_REVIEW_REQUIRED');
  need(typeof reason === 'string' && reason.normalize('NFC').trim().length >= 1 &&
    reason.normalize('NFC').trim().length <= 240 && !/[\x00-\x1f\x7f]/.test(reason),
  'PREAPPROVAL_REASON_REQUIRED');
  const current = await chain(operation);
  if (current.pending) {
    need(current.pending.sourceAttemptSha256 === expectedAttemptSha256, 'PREAPPROVAL_ATTEMPT_CHANGED');
    await verifySources(current.pending.plan);
    return preparedView(current.pending);
  }
  const sources = await readSources(operation, current);
  need(sources.find(value => value.name === 'attempt.json').sha256 === expectedAttemptSha256,
    'PREAPPROVAL_ATTEMPT_CHANGED');
  const checked = await processProof(operation, current, sources, nativeRecord, signal);
  const originalLedgerCheck = await ledgerProof(operation, current, signal);
  const native = await operation.buyer.runtime.checked(['--review', '--config', operation.configPath],
    { stateDirectory: operation.buyer.stateDirectory, mode: 'OFFLINE_REVIEW', signal });
  const { meta } = current;
  need(native.intentId === operation.intentId && native.bodySha256 === meta.bodySha256 &&
    (native.operationTicket?.sha256 ?? null) === (meta.ticketSha256 ?? null), 'NATIVE_REVIEW_MISMATCH');
  const review = { intentId: operation.intentId, configSha256: meta.configSha256,
    bodySha256: meta.bodySha256, ticketSha256: meta.ticketSha256 ?? null,
    ...(meta.nativeWorkspace ? { nativeWorkspace: meta.nativeWorkspace } : {}),
    native, reviewedAt: now() };
  const wireCheckpoint=await inspectPreapprovalWireCheckpoint(await wireInput(operation,current));
  const directory = join(operation.directory, 'preapproval-history', expectedAttemptSha256);
  const plan = {
    schema: SCHEMA, intentId: operation.intentId, operationDirectory: operation.directory, directory,
    sourceDirectory: current.directory, sourceAttemptSha256: expectedAttemptSha256,
    configSha256: meta.configSha256, bodySha256: meta.bodySha256, ticketSha256: meta.ticketSha256 ?? null,
    nativeWorkspace: meta.nativeWorkspace ?? null, reason: reason.normalize('NFC').trim(), createdAt: now(),
    sources: sources.map(details), processProof: checked.proof, processRequest: checked.request,
    originalLedgerCheck, review, reviewSha256: digest(jsonBytes(review)), wireCheckpoint,
  };
  await verifySources(plan);
  checkSignal(signal);
  await privateDirectory(join(operation.directory, 'preapproval-history'));
  await privateDirectory(directory);
  const planPath = join(directory, 'plan.json');
  if (await exists(planPath)) {
    const existingRaw = await readBytes(planPath, 262144);
    const existing = validPlan(parseJson(existingRaw), operation, directory);
    need(existing.sourceAttemptSha256 === expectedAttemptSha256 &&
      existing.configSha256 === plan.configSha256 && existing.reason === plan.reason,
    'PREAPPROVAL_DIFFERENT_PLAN_ALREADY_RETAINED');
    await verifySources(existing);
    await verifyArchive(existing);
    const link = { schema: SCHEMA, intentId: operation.intentId, directory,
      sourceAttemptSha256: expectedAttemptSha256, planSha256: digest(existingRaw) };
    if (!await exists(join(current.directory, 'preapproval-continuation.json')))
      await writeJson(join(current.directory, 'preapproval-continuation.json'), link, { exclusive: true });
    return preparedView({ ...link, plan: existing });
  }
  await privateDirectory(join(directory, 'original'));
  for (const value of sources) {
    if (!value.exists) continue;
    const archive = join(directory, 'original', value.name);
    if (await exists(archive))
      need(digest(await readBytes(archive, Math.max(value.bytes, 1))) === value.sha256,
        'PREAPPROVAL_ARCHIVE_CHANGED');
    else await writeBytes(archive, value.raw, { exclusive: true });
  }
  const retainedReviewPath = join(directory, 'review.json');
  if (await exists(retainedReviewPath)) {
    const retainedReview = await readJson(retainedReviewPath, 262144);
    need(retainedReview.intentId === operation.intentId &&
      retainedReview.configSha256 === meta.configSha256 && retainedReview.bodySha256 === meta.bodySha256 &&
      (retainedReview.ticketSha256 ?? null) === (meta.ticketSha256 ?? null) &&
      (retainedReview.nativeWorkspace ?? null) === (meta.nativeWorkspace ?? null) &&
      retainedReview.native?.intentId === operation.intentId &&
      retainedReview.native?.bodySha256 === meta.bodySha256, 'PREAPPROVAL_REVIEW_BINDING_CHANGED');
    plan.review = retainedReview;
    plan.reviewSha256 = digest(jsonBytes(retainedReview));
  } else await writeJson(retainedReviewPath, review, { exclusive: true });
  const processRequestPath = join(directory, 'process-request.json');
  if (await exists(processRequestPath))
    need(digest(await readBytes(processRequestPath, 262144)) === digest(jsonBytes(plan.processRequest)),
      'PREAPPROVAL_PROCESS_REQUEST_CHANGED');
  else await writeJson(processRequestPath, plan.processRequest, { exclusive: true });
  await verifyArchive(plan);
  await writeJson(planPath, plan, { exclusive: true });
  const planSha256 = digest(await readBytes(planPath, 262144));
  await verifySources(plan);
  const link = { schema: SCHEMA, intentId: operation.intentId, directory,
    sourceAttemptSha256: expectedAttemptSha256, planSha256 };
  await writeJson(join(current.directory, 'preapproval-continuation.json'), link, { exclusive: true });
  return preparedView({ ...link, plan });
}

export async function executePreapprovalRecovery(operation,
  { expectedPlanSha256, review, signal } = {}) {
  checkSignal(signal);
  need(HASH.test(expectedPlanSha256 ?? ''), 'PREAPPROVAL_PLAN_REVIEW_REQUIRED');
  const initial=await chain(operation),selected=initial.pending;
  need(selected && selected.planSha256===expectedPlanSha256,'PREAPPROVAL_PREPARED_PLAN_REQUIRED');
  const plan=selected.plan;
  need(object(review) && digest(jsonBytes(review))===plan.reviewSha256,'MATCHING_REVIEW_REQUIRED');
  const reserveFile=await operation.buyer.runtime.fileReservation();
  return withPreapprovalWireHistory({...await wireInput(operation,initial),
    historyDirectory:plan.directory,planSha256:expectedPlanSha256,
    sourceAttemptSha256:plan.sourceAttemptSha256,expectedCheckpoint:plan.wireCheckpoint,
    reserveFile,signal,
    verifyOriginal:async()=>{
      const current=await chain(operation);
      need(current.pending?.planSha256===expectedPlanSha256,'PREAPPROVAL_PREPARED_PLAN_REQUIRED');
      await verifySources(plan);
      const sourceAttempt=parseJson(await readBytes(join(plan.sourceDirectory,'attempt.json'),attemptRecordLimit));
      const originalCurrent={...current,directory:plan.sourceDirectory,attempt:sourceAttempt};
      const sources=await readSources(operation,originalCurrent,plan);
      const checked=await processProof(operation,originalCurrent,sources,plan.processRequest.nativeRecord,signal);
      const originalLedgerCheck=await ledgerProof(operation,current,signal);
      await verifySources(plan);
      checkSignal(signal);
      const executionCheck={schema:SCHEMA,intentId:operation.intentId,planSha256:expectedPlanSha256,
        checkedAt:now(),processProof:checked.proof,originalLedgerCheck};
      const checksDirectory=join(current.directory,'checks');
      await privateDirectory(checksDirectory);
      await writeJson(join(checksDirectory,digest(jsonBytes(executionCheck))+'.json'),executionCheck,{exclusive:true});
      return executionCheck;
    },
  },async({history,originalVerification})=>{
    const current=await chain(operation);
    need(current.pending?.planSha256===expectedPlanSha256 && history.status==='RETAINED',
      'PREAPPROVAL_PREPARED_PLAN_REQUIRED');
    const {meta,config}=current;
    let command={args:['--execute','--config',operation.configPath],entryFile:operation.buyer.runtime.cli};
    if(meta.nativeWorkspace)command=workspaceCommand(operation.buyer,{
      directory:meta.nativeWorkspace,configPath:operation.configPath,ticketSha256:meta.ticketSha256??null});
    const checkSha256=digest(jsonBytes(originalVerification));
  const reservation = plan.sources.find(value => value.name === 'download-reservation.json');
  if (reservation?.exists) {
    const released = join(current.directory, 'released-download-reservation.json');
    if (await exists(released)) {
      const observed = await snapshot(reservation.name, released, { limit: 16384 });
      need(observed.sha256 === reservation.sha256 && observed.device === reservation.device &&
        observed.inode === reservation.inode && !await exists(reservation.path),
      'PREAPPROVAL_DOWNLOAD_RESERVATION_CHANGED');
    } else {
      const observed = await snapshot(reservation.name, reservation.path, { limit: 16384 });
      need(observed.sha256 === reservation.sha256 && observed.device === reservation.device &&
        observed.inode === reservation.inode, 'PREAPPROVAL_DOWNLOAD_RESERVATION_CHANGED');
      try { await rename(reservation.path, released); }
      catch (error) {
        if (error.code !== 'ENOENT') throw error;
        const moved = await snapshot(reservation.name, released, { limit: 16384 });
        need(moved.sha256 === reservation.sha256 && moved.device === reservation.device &&
          moved.inode === reservation.inode, 'PREAPPROVAL_DOWNLOAD_RESERVATION_CHANGED');
      }
      await syncDirectory(dirname(reservation.path)); await syncDirectory(current.directory);
    }
  }
  await verifySources(plan);
  checkSignal(signal);
  const createdAt = now();
  let attempt = { schema: NODE_SCHEMA, intentId: operation.intentId, state: 'STARTING',
    createdAt, startedAt: createdAt, executionCheckSha256: checkSha256,
    configSha256: meta.configSha256, bodySha256: meta.bodySha256, retry: 'NO_AUTOMATIC_RETRY',
    preapprovalRecovery: { planSha256: expectedPlanSha256, sourceAttemptSha256: plan.sourceAttemptSha256,
      wireSelectionSha256:history.selectionSha256,wireRetirementSha256:history.retirementSha256 },
  };
  const attemptPath = join(current.directory, 'attempt.json');
  const reservations = await prepareWriteReservations([
    { path: attemptPath, bytes: attemptRecordLimit, exclusive: true },
    { path: attemptPath, bytes: attemptRecordLimit },
    { path: attemptPath, bytes: attemptRecordLimit },
    { path: attemptPath, bytes: attemptRecordLimit },
    { path: join(current.directory, 'result.json'),
      bytes: resultRecordLimit(operation.buyer.runtime), exclusive: true },
  ], { reserveFile, signal });
  const recordAttempt = async () => {
    try { await writeJson(attemptPath, attempt, { exclusive: true }); }
    catch (error) {
      if (error.code === 'EEXIST') throw new BuyerError('ATTEMPT_ALREADY_RECORDED_USE_RECOVER', { operation });
      throw error;
    }
    let run;
    try {
      run = await operation.buyer.runtime.run(command.args, {
        directory: current.directory, signal, entryFile: command.entryFile,
        beforeSpawn: async nativeCommand => {
          await verifySources(plan);
          const retainedWire=await selectedWireHistory(operation,current,selected);
          need(retainedWire?.retirementSha256===history.retirementSha256,
            'PREAPPROVAL_WIRE_RETIREMENT_CHANGED');
          attempt = { ...attempt, nativeCommand };
          await writeJson(attemptPath, attempt);
        },
        started: async (pid, processIdentity) => {
          attempt = { ...attempt, state: 'STARTED', pid, startedAt: now(),
            ...(processIdentity ? { processIdentity } : {}) };
          await writeJson(attemptPath, attempt);
        },
      });
    } catch (error) {
      await writeJson(attemptPath, unstartedAttempt(attempt, error) ??
        { ...attempt, state: 'INTERRUPTED_OR_START_FAILED', endedAt: now() });
      throw error;
    }
    if (run.output?.mode !== NATIVE_RESULT || run.output.intentId !== operation.intentId) {
      await writeJson(attemptPath, unstartedAttempt(attempt, run) ??
        { ...attempt, state: 'NATIVE_RESULT_UNAVAILABLE', endedAt: now(),
          exitCode: run.exitCode, errorCode: run.errorCode ?? 'NATIVE_RESULT_INVALID' });
      throw new BuyerError(run.errorCode ?? 'NATIVE_RESULT_INVALID', { operation, exitCode: run.exitCode });
    }
    const record = { schema: NODE_SCHEMA, intentId: operation.intentId, configSha256: meta.configSha256,
      native: run.output, exitCode: run.exitCode, exitSignal: run.exitSignal,
      runtimeError: run.errorCode, recovered: false, recordedAt: now(),
      preapprovalRecovery: { directory: current.directory, planSha256: expectedPlanSha256,
        sourceAttemptSha256: plan.sourceAttemptSha256 },
    };
    await writeJson(join(current.directory, 'result.json'), record, { exclusive: true });
    await writeJson(attemptPath, { ...attempt, state: 'RECORDED', exitCode: run.exitCode, endedAt: now() });
    return operation._result(record);
  };
  try { return reservations ? await reservations.run(recordAttempt) : await recordAttempt(); }
  finally { await reservations?.close(); }

  });
}

export async function recoverPreapprovalResult(operation) {
  const current = await chain(operation);
  if (!current.history.length || !current.attempt) return null;
  if (await exists(join(current.directory, 'result.json')))
    return operation._result(await readJson(join(current.directory, 'result.json'), resultRecordLimit(operation.buyer.runtime)));
  let native;
  try { native = await readJson(join(current.directory, 'stdout.json'), operation.buyer.runtime.outputLimit); }
  catch (error) { if (['ENOENT', 'JSON_INVALID'].includes(error.code)) return null; throw error; }
  if (native.mode !== NATIVE_RESULT || native.intentId !== operation.intentId) return null;
  return operation._result({ schema: NODE_SCHEMA, intentId: operation.intentId,
    configSha256: current.meta.configSha256, native, exitCode: null, exitSignal: null,
    runtimeError: 'PROCESS_EXIT_NOT_RECORDED', recovered: true, recordedAt: now(),
    preapprovalRecovery: { directory: current.directory, planSha256: current.history.at(-1).planSha256 },
  });
}

// MIT. Capture an actual Linux child identity once, at native launch.
// PID alone never authorizes recovery. Missing or raced observations stay explicit.
import { readFile, readlink, readdir, stat } from 'node:fs/promises';

const SCHEMA = 'stellar-forge.node-process-identity.v1';
const vanished = error => ['ENOENT', 'ESRCH'].includes(error?.code);

function procStat(raw) {
  const close = raw.lastIndexOf(')');
  if (close < 1) throw new Error('PROCESS_STAT_INVALID');
  const pid = Number(raw.slice(0, raw.indexOf(' ')));
  const fields = raw.slice(close + 2).trim().split(/\s+/);
  if (!Number.isSafeInteger(pid) || pid < 1 || fields.length < 20 ||
      !/^\d+$/.test(fields[19]) || !/^\d+$/.test(fields[1]))
    throw new Error('PROCESS_STAT_INVALID');
  return { procPid: pid, parentProcPid: Number(fields[1]), startTicks: fields[19] };
}

async function sample(procPid) {
  const base = '/proc/' + procPid;
  const before = procStat(await readFile(base + '/stat', 'utf8'));
  const [namespace, status] = await Promise.all([
    readlink(base + '/ns/pid'), readFile(base + '/status', 'utf8'),
  ]);
  const match = /^NSpid:\s+([0-9 \t]+)$/m.exec(status);
  if (!match || !/^pid:\[\d+\]$/.test(namespace)) throw new Error('PROCESS_NAMESPACE_UNAVAILABLE');
  const namespacePids = match[1].trim().split(/\s+/).map(Number);
  const after = procStat(await readFile(base + '/stat', 'utf8'));
  if (before.procPid !== after.procPid || before.startTicks !== after.startTicks ||
      before.parentProcPid !== after.parentProcPid)
    throw new Error('PROCESS_IDENTITY_CHANGED');
  return { ...after, namespace, namespacePids };
}

export async function captureChildProcessIdentity(pid) {
  const unavailable = reason => ({ schema: SCHEMA, status: 'UNAVAILABLE', pid, reason });
  if (process.platform !== 'linux') return unavailable('LINUX_PROCESS_IDENTITY_UNAVAILABLE');
  if (!Number.isSafeInteger(pid) || pid < 1) return unavailable('CHILD_PID_INVALID');
  try {
    const procfsDevice = (await stat('/proc', { bigint: true })).dev.toString();
    const bootId = (await readFile('/proc/sys/kernel/random/boot_id', 'utf8')).trim();
    if (!/^[a-f0-9-]{36}$/.test(bootId)) return unavailable('BOOT_ID_UNAVAILABLE');
    const ownStat = procStat(await readFile('/proc/self/stat', 'utf8'));
    const ownNamespace = await readlink('/proc/self/ns/pid');
    const own = await sample(ownStat.procPid);
    const matches = candidate => candidate.namespace === ownNamespace &&
      candidate.namespacePids.at(-1) === pid && candidate.parentProcPid === own.procPid;
    const childCandidate = async procPid => {
      // A container PID may name an unrelated host process in this procfs.
      // Establish parent ownership before following a namespace link.
      const candidate = procStat(await readFile('/proc/' + procPid + '/stat', 'utf8'));
      if (candidate.parentProcPid !== own.procPid) return null;
      return sample(procPid);
    };
    let child = null;
    try { const direct = await childCandidate(pid); if (direct && matches(direct)) child = direct; }
    catch (error) { if (!vanished(error)) throw error; }
    if (!child) {
      // A container may expose a parent namespace's procfs. Resolve the child's
      // actual NSpid and namespace once, rather than treating an aliased PID as it.
      const entries = (await readdir('/proc')).filter(name => /^[1-9]\d*$/.test(name));
      if (entries.length > 131072) return unavailable('PROCESS_TABLE_LIMIT');
      for (const name of entries) {
        let candidate;
        try { candidate = await childCandidate(Number(name)); }
        catch (error) { if (vanished(error)) continue; throw error; }
        if (!candidate || !matches(candidate)) continue;
        if (child) return unavailable('CHILD_IDENTITY_AMBIGUOUS');
        child = candidate;
      }
    }
    if (!child) return unavailable('CHILD_ENDED_BEFORE_IDENTITY_CAPTURE');
    const checked = await sample(child.procPid);
    const parent = await sample(own.procPid);
    if (!matches(checked) || checked.startTicks !== child.startTicks ||
        parent.startTicks !== own.startTicks ||
        (await stat('/proc', { bigint: true })).dev.toString() !== procfsDevice ||
        (await readFile('/proc/sys/kernel/random/boot_id', 'utf8')).trim() !== bootId)
      return unavailable('PROCESS_IDENTITY_CHANGED');
    return {
      schema: SCHEMA, status: 'RECORDED', pid, procPid: checked.procPid,
      startTicks: checked.startTicks, namespace: checked.namespace, bootId, procfsDevice,
      parent: { procPid: parent.procPid, startTicks: parent.startTicks, namespace: parent.namespace },
      capturedAt: new Date().toISOString(),
    };
  } catch (error) {
    return unavailable(vanished(error) ? 'CHILD_ENDED_BEFORE_IDENTITY_CAPTURE' : 'PROCESS_IDENTITY_NOT_OBSERVED');
  }
}

