      request.expect.asset === terms.asset && request.expect.payTo === terms.payTo &&
      terms.extra?.paymentFlow === 'authorization' && BigInt(terms.amount) <= BigInt(maxAtomic),
    'UNSTRUCTURED_REVIEWED_PAYMENT_OPTION_MISMATCH');
