/* MIT. Managed document processing in the original research workspace. */
.pipelines-panel { color: #222; }
.pipelines-panel h3 { margin: 0 0 .7rem; }
.pipelines-panel h4 { margin: 1.2rem 0 .55rem; font-size: .95rem; }
.pipelines-panel label { display: flex; flex-direction: column; gap: .35rem; min-width: 0; font-size: .87rem; }
.pipelines-panel input, .pipelines-panel select, .pipelines-panel textarea { min-width: 0; width: 100%; box-sizing: border-box; background: #fff; color: #222; border: 1px solid #aaa; border-radius: 3px; padding: .55rem; }
.pipelines-panel input[type=file] { padding: .55rem; }
.pipelines-panel textarea { resize: vertical; }
.pipelines-panel button { background: #fff; color: #222; border: 1px solid #999; border-radius: 3px; padding: .55rem .75rem; font: inherit; font-size: .85rem; cursor: pointer; }
.pipelines-panel button:hover:not(:disabled) { background: #eee; border-color: #555; }
.pipelines-panel button.primary { background: #303030; border-color: #303030; color: #fff; }
.pipelines-panel button.primary:hover:not(:disabled) { background: #111; }
.pipelines-panel button:disabled, .pipelines-panel input:disabled, .pipelines-panel select:disabled, .pipelines-panel textarea:disabled { cursor: default; opacity: .55; }
.pipelines-panel :focus-visible { outline: 2px solid #222; outline-offset: 3px; }
.pipelines-panel [hidden] { display: none !important; }
.pipelines-panel .muted { color: #626262; }
.pipelines-panel .form-error { grid-column: 1 / -1; white-space: pre-wrap; color: #222; border-left: 3px solid #444; padding-left: .7rem; }
.pipelines-panel .button-row { display: flex; flex-wrap: wrap; gap: .5rem; align-items: center; margin: .65rem 0; }
.pipelines-panel .view-heading { align-items: flex-start; gap: 1rem; }
.pipelines-panel .view-heading h2 { margin-bottom: .3rem; }
.pipelines-panel .view-heading p { max-width: 60rem; }
.pipelines-intake { border: 1px solid #c2c2c2; background: #f6f6f6; padding: 1rem; margin: 1.2rem 0; }
.pipelines-intake > summary { font-weight: 600; cursor: pointer; }
.pipelines-intake form { padding-top: 1rem; }
.pipelines-fields { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: .8rem; align-items: end; margin: .7rem 0; }
.pipelines-fields > button { justify-self: start; align-self: end; }
.pipelines-file-list { margin: .6rem 0; padding-left: 1.4rem; }
.pipelines-file-list li { padding: .2rem 0; overflow-wrap: anywhere; font-size: .87rem; }
.pipelines-layout { display: grid; grid-template-columns: minmax(14rem,19rem) minmax(0,1fr); gap: 1.3rem; align-items: start; }
.pipelines-history { border-right: 1px solid #ccc; padding-right: 1rem; min-width: 0; }
.pipelines-history h3:not(:first-child) { margin-top: 1.7rem; }
.pipelines-main { min-width: 0; }
.pipelines-panel button.pipelines-item { width: 100%; display: flex; flex-direction: column; gap: .35rem; text-align: left; margin: 0 0 .5rem; padding: .75rem; overflow-wrap: anywhere; }
.pipelines-panel button.pipelines-item.active { background: #e9e9e9; border-color: #333; box-shadow: inset 3px 0 0 #333; }
.pipelines-item strong { font-size: .9rem; font-weight: 600; }
.pipelines-item span { font-size: .77rem; line-height: 1.4; }
.pipelines-facts { display: grid; grid-template-columns: minmax(7rem,10rem) minmax(0,1fr); gap: .4rem 1rem; padding: .8rem; background: #f4f4f4; font-size: .84rem; }
.pipelines-facts dt { color: #666; }
.pipelines-facts dd { margin: 0; overflow-wrap: anywhere; }
.pipelines-input-row { display: flex; justify-content: space-between; gap: .8rem; align-items: center; border-bottom: 1px solid #ddd; padding: .55rem 0; font-size: .84rem; }
.pipelines-input-row span { overflow-wrap: anywhere; min-width: 0; }
.pipelines-input-row button { flex-shrink: 0; }
.pipelines-submit { margin: 1rem 0; padding: .8rem; border: 1px solid #bbb; }
.pipelines-panel label.pipelines-check { flex-direction: row; align-items: flex-start; gap: .6rem; line-height: 1.5; }
.pipelines-check input[type=checkbox] { width: auto; flex-shrink: 0; margin-top: .2rem; }
.pipelines-inline { display: flex; flex-wrap: wrap; align-items: end; gap: .7rem; margin: .85rem 0; }
.pipelines-inline > label { flex: 1 1 16rem; }
.pipelines-inline > .form-error { flex: 1 1 100%; }
.pipelines-reconcile { margin: 1rem 0; border-block: 1px solid #ccc; padding: .85rem 0; }
.pipelines-reconcile > summary { cursor: pointer; font-weight: 600; }
.pipelines-reconcile form > label { margin-bottom: .8rem; }
.pipelines-actions { margin: 1rem 0; }
.pipelines-panel .original-record { margin: .8rem 0; }
.pipelines-panel .original-record summary { cursor: pointer; font-size: .86rem; }
.pipelines-panel pre { white-space: pre-wrap; overflow-wrap: anywhere; font-size: .77rem; line-height: 1.5; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; background: #f3f3f3; border: 1px solid #ddd; padding: .8rem; max-height: 28rem; overflow: auto; }
.pipelines-panel pre:empty { display: none; }
.pipelines-output-row { display: flex; flex-wrap: wrap; align-items: center; gap: .55rem; margin-bottom: .65rem; }
.pipelines-output-row > .pipelines-item { flex: 1 1 18rem; margin: 0 !important; width: auto !important; }
.pipelines-output-row > button:last-child { flex: 0 0 auto; }
.pipelines-review { margin-top: 1.5rem; padding-top: 1.2rem; border-top: 2px solid #555; }
.pipelines-review #pipelines-filter { grid-template-columns: minmax(6rem,.7fr) minmax(8rem,1fr) minmax(10rem,1.6fr) auto; }
.pipelines-panel button.pipelines-element { width: 100%; text-align: left; display: flex; flex-direction: column; gap: .4rem; border: 1px solid #ccc; padding: .8rem; margin-bottom: .5rem; }
.pipelines-element strong { font-size: .86rem; }
.pipelines-element span { overflow-wrap: anywhere; }
.pipelines-excerpt { line-height: 1.5; white-space: pre-wrap; font-size: .84rem; }
.pipelines-element-detail { margin: 1rem 0; padding: .8rem; border: 1px solid #aaa; }
.pipelines-panel .pagination { display: flex; align-items: center; justify-content: space-between; gap: .7rem; margin: 1rem 0; font-size: .82rem; }
.pipelines-recovery { padding: .9rem; background: #eaeaea; border: 1px solid #999; margin: 1rem 0; }
.pipelines-recovery h3 { font-size: .96rem; }
.pipelines-recovery-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .6rem; padding: .45rem 0; }
.pipelines-recovery-row span { flex: 1 1 20rem; overflow-wrap: anywhere; font-size: .82rem; }
@media(max-width: 1100px) {
  .pipelines-layout { grid-template-columns: minmax(12rem,15rem) minmax(0,1fr); gap: 1rem; }
  .pipelines-fields, .pipelines-review #pipelines-filter { grid-template-columns: repeat(2,minmax(0,1fr)); }
}
@media(max-width: 760px) {
  .pipelines-layout { grid-template-columns: minmax(0,1fr); }
  .pipelines-history { border-right: 0; border-bottom: 1px solid #ccc; padding: 0 0 1rem; }
  .pipelines-fields, .pipelines-review #pipelines-filter { grid-template-columns: minmax(0,1fr); }
  .pipelines-facts { grid-template-columns: minmax(0,1fr); }
  .pipelines-facts dd { margin-bottom: .5rem; }
  .pipelines-panel .view-heading { flex-direction: column; }
}

import {createObjectInputsPanel} from './object-inputs.js';
// MIT. Managed document processing in the original research dossier workspace.
export function createUnstructuredPipelinesPanel({root,tab,api,task,notify,getDossier,onReceived,isBusy}){
  const array=value=>Array.isArray(value)?value:[];
