      for (const id of states.keys()) if (!unique.has(id)) throw new Error('ORPHAN_DELIVERY:' + id);
      return [...unique.values()].map(event => ({ event, state: states.get(event.id) ?? null }));
    },
    async status() {
      const rows = await this.rows();
